vertex.source:
#version 300 es

// Vertex position in object space coordinates
in vec3 vertexPosition;
// Surface normal at the vertex in object space coordinates
in vec3 vertexNormal;
// Texture coordinates at that vertex
in vec2 vertexTextureCoordinates;

uniform vec4 lightPosition;
uniform bool lightInCamspace;

// Model matrix
uniform mat4 mMatrix;
// View matrix
uniform mat4 vMatrix;
// Projection matrix
uniform mat4 pMatrix;

// Main program for each vertex
void main() {
  vec4 vertexCamSpace = vMatrix * mMatrix * vec4(vertexPosition, 1.0);
  gl_Position = pMatrix * vertexCamSpace;
}

fragment.source:
#version 300 es

// For better performance less precision
precision highp float;

uniform vec4 lightPosition;
uniform bool lightInCamspace;

out vec4 fragColor;

// Main program for each fragment = pixel candidate
void main() {
  fragColor = vec4(1.0, 0.0, 0.0, 1.0);
}

vertex.source:
#version 300 es

// Vertex coordinates in object space for the render quad
in vec3 vertexPosition;

uniform float canvasWidth;
uniform float canvasHeight;

uniform vec3 cameraPosition;
uniform mat3 cameraRotation;

uniform bool isOrthographicProjection;
uniform float orthographicFOV;
uniform float perspectiveFOV;

out vec3 origin;
out vec3 dir;

void main() {
    float aspectRatio = canvasWidth/canvasHeight;
    vec3 origin_camSpace, dir_camSpace;
    if (isOrthographicProjection) {
        origin_camSpace = vec3(vertexPosition.x*orthographicFOV*aspectRatio,
                                vertexPosition.y*orthographicFOV,
                                0);
        dir_camSpace = vec3(0, 0, -1);
    }
    else { // perspective projection
        origin_camSpace = vec3(0);
        dir_camSpace = vec3(vertexPosition.x*aspectRatio,
                            vertexPosition.y,
                            -1.0/tan(radians(perspectiveFOV)));
    }
    origin = cameraPosition + cameraRotation*origin_camSpace;
    dir = normalize(cameraRotation*dir_camSpace);
    gl_Position = vec4(vertexPosition, 1.0);
}

fragment.source:
#version 300 es

precision highp float;

in vec3 origin;
in vec3 dir;

out vec4 fragColor;


struct Sphere {
    vec3 centre;
    float radius;
    vec3 colour;
};

struct Plane {
    vec3 point;
    vec3 normal;
    vec3 colour;
};


vec3 intersection(vec3 origin, vec3 dir, float dist) {
    return origin + normalize(dir) * dist;
}

float intersect_sphere(vec3 origin, vec3 dir, Sphere sphere) {
    vec3 p_0 = origin;
    vec3 d = normalize(dir);
    vec3 p_s = sphere.centre;
    vec3 del_p = p_0 - p_s;
    float r = sphere.radius;

    float det = 0.;
    det += dot(d, del_p) * dot(d, del_p);
    det -= dot(del_p, del_p);
    det += r * r;

    float mu = 0.;
    if (det < 0.) mu = -1.;
    else mu = - dot(d, del_p) - sqrt(det);

    return mu;
}

float intersect_plane(vec3 origin, vec3 dir, Plane plane) {
    vec3 p_0 = origin;
    vec3 d = normalize(dir);
    vec3 p_1 = plane.point;
    vec3 n = normalize(plane.normal);

    float mu = - dot((p_0 - p_1), n) / dot(d, n);
    return mu;
}

vec4 trace(vec3 intersection, vec3 direction, vec3 light, Sphere sphere) {
    vec3 n = normalize(intersection - sphere.centre);
    vec3 l = normalize(light - intersection);
    vec3 r = normalize(2. * dot(n, l) * n - l);
    vec3 v = -normalize(direction);

    float shininess = 8.;
    float atten = 1. / length(intersection - light);
    float I = 9. * atten;

    vec4 ambientCol = vec4(0, 0, 0, 1.);
    vec4 diffuseCol = clamp(I * max(0., dot(n, l)) * vec4(sphere.colour, 1.), 0., 1.);
    vec4 specularCol = clamp(I * pow(max(0.0, dot(r, v)), shininess) * vec4(sphere.colour, 1.0), 0., 1.);

    return ambientCol + diffuseCol + specularCol;
}

bool is_obsecured(vec3 origin, vec3 light, Sphere sphere) {
    return (intersect_sphere(origin, normalize(light-origin), sphere) > -0.);
}

// Main program for each fragment of the render quad
void main() {
    // scene def start
    Sphere sphere[6];
    Plane plane;
    sphere[0].centre = vec3(-2.0, 1.5, -3.5);
    sphere[0].radius = 1.5;
    sphere[0].colour = vec3(0.8,0.8,0.8);
    sphere[1].centre = vec3(-0.5, 0.0, -2.0);
    sphere[1].radius = 0.6;
    sphere[1].colour = vec3(0.3,0.8,0.3);
    sphere[2].centre = vec3(1.0, 0.7, -2.2);
    sphere[2].radius = 0.8;
    sphere[2].colour = vec3(0.3,0.8,0.8);
    sphere[3].centre = vec3(0.7, -0.3, -1.2);
    sphere[3].radius = 0.2;
    sphere[3].colour = vec3(0.8,0.8,0.3);
    sphere[4].centre = vec3(-0.7, -0.3, -1.2);
    sphere[4].radius = 0.2;
    sphere[4].colour = vec3(0.8,0.3,0.3);
    sphere[5].centre = vec3(0.2, -0.2, -1.2);
    sphere[5].radius = 0.3;
    sphere[5].colour = vec3(0.8,0.3,0.8);
    plane.point = vec3(0,-0.5, 0);
    plane.normal = vec3(0, 1.0, 0);
    plane.colour = vec3(1, 1, 1);
    vec3 light = vec3(6., 4., 3.); 
    // scene def end

    vec4 color = vec4(0., 0., 0., 1.);
    vec3 next_origin = origin;
    vec3 next_direction = dir;
    float ratio = .8;
    float k_refl = .6;

    for (int depth = 0; depth < 42; ++depth) {   
        float min_dist = -1.;
        float dist;
        vec3 potential_next_origin;
        vec3 potential_next_direction;
        vec3 potential_normal;
        vec4 potential_color;

        // check all spheres
        for (int i = 0; i < 6; ++i) {
            Sphere curr = sphere[i];
            dist = intersect_sphere(next_origin, next_direction, curr);
            if (min_dist <= 0. && dist >= 0. || dist >= 0. && dist <= min_dist) {
                min_dist = dist;
                potential_next_origin = intersection(next_origin, next_direction, dist);
                potential_normal = normalize(potential_next_origin - curr.centre);
                // potential_next_direction = normalize(2. * dot(potential_normal, -next_direction) * potential_normal + next_direction);
                potential_color = ratio * trace(potential_next_origin, next_direction, light, curr);
            }
        }

        // check planes
        dist = intersect_plane(next_origin, next_direction, plane);
        if ((min_dist <= 0. && dist >= 0.) ||  (dist >= 0. && dist < min_dist)) {
            min_dist = dist;
            potential_next_origin = intersection(next_origin, next_direction, dist);
            potential_next_origin += plane.normal * 0.00001;

            float atten = 1. / length(potential_next_origin - light);
            float I = 8. * atten;
            float forward = floor(potential_next_origin.z);
            float lateral = floor(potential_next_origin.x);
            if (mod(forward, 2.0) == 0. && mod(lateral, 2.0) == 0. || mod(forward, 2.0) == 1. && mod(lateral, 2.0) == 1.) 
                potential_color = ratio * vec4(0., 0., 0., 1.) * I;
            else 
                potential_color = ratio * vec4(plane.colour, 1.) * I;
            potential_normal = normalize(plane.normal);
        }

        if (min_dist == -1.) break;

        bool is_obsc = false;
        for (int j = 0; j < 6; ++j) {
            is_obsc = is_obsc || is_obsecured(potential_next_origin, light, sphere[j]);
        }

        if (!is_obsc) color += clamp(ratio * potential_color, 0., 1.);
        else color += clamp(.4 * ratio * potential_color, 0., 1.);

        next_origin = potential_next_origin;
        next_direction = normalize(2. * dot(potential_normal, -next_direction) * potential_normal + next_direction);
        ratio *= k_refl;
    }

    fragColor = color;
}
